import requests
import json

# Try fpbase API directly with known protein names
fp_names = {
    "5JZL": "usGFP",
    "2H5Q": "mCherry",
    "3ADF": "Azami",
    "5WJ2": "Clover",
    "3M22": "TagRFP",
}

results = {}
for pdb_id, name in fp_names.items():
    try:
        # Try direct API query
        url = f"https://www.fpbase.org/api/protein/?name__icontains={name}"
        response = requests.get(url, timeout=5)
        print(f"Status {pdb_id}: {response.status_code}")
        if response.status_code == 200:
            data = response.json()
            print(f"Response type: {type(data)}")
            if isinstance(data, dict):
                print(f"Keys: {list(data.keys())[:5]}")
            elif isinstance(data, list):
                if len(data) > 0:
                    p = data[0]
                    ex = p.get('ex_max', p.get('excitation_max'))
                    em = p.get('em_max', p.get('emission_max'))
                    print(f"{pdb_id} {name}: ex={ex}, em={em}")
                    results[pdb_id] = {'ex_max': ex, 'em_max': em}
    except Exception as e:
        print(f"Error {pdb_id}: {str(e)[:80]}")

print(f"\nFound data for {len(results)} proteins")
